/** Codec key for a platform-1 record, or null when no codec is defined (Arabic, Hebrew, ...). */
export function macCodecKey(encodingID, languageID) {
  if (encodingID === 0) return ROMAN_LANG[languageID] || 'roman';
  return ENC[encodingID] || null;
}
